pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 1;
        vm.prank(attacker);
        bool ok;
        try c.transfer(tos, amounts) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok); // Reference reverts, buggy does not revert => ok = true, so assertTrue(!ok) catches the bug
    }
}

