// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address _from = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        address[] memory _tos = new address[](1);
        _tos[0] = 0x0000000000000000000000000000000000000001;
        uint[] memory v = new uint[](1);
        v[0] = 1;
        vm.prank(_from);
        bool ok;
        try c.transfer(_tos, v) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }
        assertTrue(ok, "Reference should return true, buggy reverts");
    }
}
